import { useEffect, useMemo, useState } from 'react';
import { analyzeExternalClientReport, getPendingExternalReportAnalyses, saveExternalReportBiomarkers } from '../../lib/externalTransientReportApi';

const STAGES=[['Reading report…','Preparing the report for analysis.'],['Extracting health parameters…',"We're identifying laboratory results from the report. This may take a few moments."],['Validating extracted values…','Checking values, units, dates and source evidence.'],['Organising biomarkers…',"Matching report values to the client's health profile."],['Preparing results for review…','Building a safe review before anything is saved.']];
const FILTERS=['All','Abnormal','Needs Review','Unmapped','Confirmed','Rejected'];
const shown=v=>v===null||v===undefined||v===''?'—':String(v);
const dateLabel=value=>{if(!value)return'Date unavailable';const date=new Date(`${value}T00:00:00Z`);return Number.isNaN(date.getTime())?value:new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(date);};
const abnormal=item=>['HIGH','LOW'].includes(item.labFlag);

function Row({item,onDecision,onCorrection}){return <article className={`rounded-2xl border p-4 ${item.decision==='REJECTED'?'border-red-200 bg-red-50':item.decision==='CONFIRMED'?'border-emerald-200 bg-emerald-50/40':item.decision==='CORRECTED'?'border-amber-200 bg-amber-50/40':'border-slate-200'}`}><div className="flex flex-col justify-between gap-3 md:flex-row"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><h5 className="font-semibold">{item.canonicalName||item.rawName}</h5><span className={`rounded-full px-2 py-1 text-[10px] font-semibold ${abnormal(item)?'bg-amber-100 text-amber-800':'bg-emerald-100 text-emerald-700'}`}>{item.labFlag||'UNKNOWN'}</span>{!item.bulkConfirmEligible&&<span className="rounded-full bg-slate-200 px-2 py-1 text-[10px] font-semibold">Needs review</span>}</div><p className="mt-1 text-sm">{shown(item.numericValue??item.rawValue)} {item.canonicalUnit||item.rawUnit||''} · {dateLabel(item.observationDate)}</p><p className="mt-1 text-xs text-slate-500">Source p. {item.sourcePage||'—'} · {item.sourceTestName||item.rawName} · Reference: {item.referenceText||'Lab reference range not provided'}</p></div><div className="flex flex-wrap gap-2">{[['CONFIRMED','Confirm'],['CORRECTED','Correct'],['REJECTED','Reject']].map(([decision,label])=><button key={decision} type="button" aria-pressed={item.decision===decision} onClick={()=>onDecision(item.rowIdentity,decision)} className={`min-h-11 rounded-lg border px-3 text-xs font-semibold ${item.decision===decision?decision==='REJECTED'?'bg-red-600 text-white':decision==='CORRECTED'?'bg-amber-500 text-white':'bg-emerald-600 text-white':''}`}>{item.decision===decision&&decision==='CONFIRMED'?'✓ Confirmed':label}</button>)}</div></div>{item.decision==='CORRECTED'&&<div className="mt-4 grid gap-3 sm:grid-cols-2"><label className="text-xs font-semibold">Corrected value<input type="number" step="any" value={item.correction?.value??item.numericValue??''} onChange={event=>onCorrection(item.rowIdentity,'value',event.target.value===''?null:Number(event.target.value))} className="mt-1 w-full rounded-xl border bg-white p-3"/></label><label className="text-xs font-semibold">Corrected unit<input value={item.correction?.unit??item.canonicalUnit??item.rawUnit??''} onChange={event=>onCorrection(item.rowIdentity,'unit',event.target.value)} className="mt-1 w-full rounded-xl border bg-white p-3"/></label><label className="text-xs font-semibold sm:col-span-2">Correction reason<input required value={item.correction?.reason??''} onChange={event=>onCorrection(item.rowIdentity,'reason',event.target.value)} className="mt-1 w-full rounded-xl border bg-white p-3"/></label></div>}</article>}

export default function ExternalBiomarkerReview({clientId,onSaved,onError}){
  const [open,setOpen]=useState(false),[file,setFile]=useState(null),[busy,setBusy]=useState(false),[stage,setStage]=useState(0),[slow,setSlow]=useState(false),[analysis,setAnalysis]=useState(null),[items,setItems]=useState([]),[notice,setNotice]=useState(''),[error,setError]=useState(''),[query,setQuery]=useState(''),[filter,setFilter]=useState('All'),[sort,setSort]=useState('Report order');
  useEffect(()=>{let active=true;getPendingExternalReportAnalyses(clientId).then(({analyses})=>{const pending=analyses?.[0];if(active&&pending){setAnalysis(pending);setItems(pending.items.map(item=>({...item,decision:'PENDING',correction:null})));setOpen(true);}}).catch(()=>undefined);return()=>{active=false;};},[clientId]);
  useEffect(()=>{if(!busy)return;const interval=window.setInterval(()=>setStage(value=>Math.min(value+1,STAGES.length-1)),1400);const timeout=window.setTimeout(()=>setSlow(true),8000);return()=>{clearInterval(interval);clearTimeout(timeout);};},[busy]);
  const counts=useMemo(()=>({total:items.length,mapped:items.filter(x=>x.canonicalId).length,needs:items.filter(x=>!x.bulkConfirmEligible||x.decision==='PENDING').length,abnormal:items.filter(abnormal).length,unmapped:items.filter(x=>!x.canonicalId).length,rejected:items.filter(x=>x.decision==='REJECTED').length,ready:items.filter(x=>['CONFIRMED','CORRECTED'].includes(x.decision)).length}),[items]);
  const visible=useMemo(()=>{let rows=items.filter(x=>(`${x.canonicalName||''} ${x.rawName} ${x.panel||''}`).toLowerCase().includes(query.toLowerCase()));if(filter==='Abnormal')rows=rows.filter(abnormal);if(filter==='Needs Review')rows=rows.filter(x=>!x.bulkConfirmEligible||x.decision==='PENDING');if(filter==='Unmapped')rows=rows.filter(x=>!x.canonicalId);if(filter==='Confirmed')rows=rows.filter(x=>['CONFIRMED','CORRECTED'].includes(x.decision));if(filter==='Rejected')rows=rows.filter(x=>x.decision==='REJECTED');if(sort==='Name')rows=[...rows].sort((a,b)=>(a.canonicalName||a.rawName).localeCompare(b.canonicalName||b.rawName));if(sort==='Abnormal first')rows=[...rows].sort((a,b)=>Number(abnormal(b))-Number(abnormal(a)));return rows;},[items,query,filter,sort]);
  const groups=useMemo(()=>Object.entries(visible.reduce((all,item)=>{(all[item.panel||'Other']??=[]).push(item);return all;},{})),[visible]);
  const decide=(id,decision)=>setItems(current=>current.map(item=>item.rowIdentity===id?{...item,decision}:item));
  const correct=(id,key,value)=>setItems(current=>current.map(item=>item.rowIdentity===id?{...item,decision:'CORRECTED',correction:{...(item.correction||{}),[key]:value}}:item));
  const analyse=async event=>{event.preventDefault();setBusy(true);setStage(0);setSlow(false);setError('');onError('');try{const result=await analyzeExternalClientReport(clientId,file);setAnalysis(result);setItems(result.items.map(item=>({...item,decision:'PENDING',correction:null})));}catch(failure){setError(failure.message||"We couldn't read this report. Please try again with a clearer copy.");}finally{setBusy(false);}};
  const save=async()=>{setBusy(true);setError('');try{const result=await saveExternalReportBiomarkers(clientId,analysis.analysisId,analysis.reviewToken,items);setNotice(`${result.savedCount} biomarkers saved. ${result.excludedCount||0} unresolved results excluded. Source file not retained.`);setOpen(false);setAnalysis(null);setItems([]);setFile(null);await onSaved();}catch(failure){setError(failure.message||"We couldn't save these results. Please try again.");}finally{setBusy(false);}};
  const correctionIncomplete=items.some(item=>item.decision==='CORRECTED'&&!item.correction?.reason?.trim());
  return <><section className="rounded-2xl border bg-white p-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><h3 className="font-semibold">Lab Analysis</h3><p className="mt-1 text-sm text-slate-500">Analyse transiently; only approved structured biomarkers are saved.</p></div><button onClick={()=>setOpen(true)} className="min-h-11 rounded-xl bg-slate-950 px-4 text-sm font-semibold text-white">Analyse Report</button></div>{notice&&<p role="status" className="mt-4 rounded-xl bg-emerald-50 p-3 text-sm text-emerald-800">{notice}</p>}</section>{open&&<div className="fixed inset-0 z-50 flex items-end bg-slate-950/50 sm:items-center sm:justify-center sm:p-4" role="dialog" aria-modal="true"><section className="max-h-[96dvh] w-full overflow-auto rounded-t-3xl bg-white p-5 sm:max-w-5xl sm:rounded-2xl sm:p-6"><header className="flex justify-between gap-3"><div><h3 className="text-xl font-semibold">Analyse lab report</h3><p className="text-sm text-slate-500">Review source-traceable values before saving.</p></div><button disabled={busy} onClick={()=>setOpen(false)} className="min-h-11 rounded-xl border px-4">Close</button></header>{error&&<div role="alert" className="mt-4 rounded-xl bg-red-50 p-3 text-sm text-red-800"><strong className="block">Biomarkers were not saved</strong>{error}</div>}{!analysis?<form onSubmit={analyse} className="mt-6 space-y-5"><label className="block rounded-2xl border-2 border-dashed p-5 text-sm font-semibold">Choose PDF, JPEG or PNG<input required disabled={busy} type="file" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" onChange={event=>setFile(event.target.files?.[0]||null)} className="mt-3 block w-full font-normal"/></label>{busy?<div role="status" aria-live="polite" className="rounded-2xl bg-blue-50 p-5"><p className="font-semibold">{STAGES[stage][0]}</p><p className="mt-2 text-sm">{STAGES[stage][1]}</p>{slow&&<p className="mt-3 text-xs">This report is taking a little longer to analyse. Please keep this page open.</p>}</div>:<button disabled={!file} className="min-h-11 w-full rounded-xl bg-blue-600 text-white disabled:opacity-40">Analyse report</button>}</form>:<div className="mt-5"><div className="rounded-2xl bg-slate-50 p-4"><div className="flex flex-wrap justify-between gap-3"><div><strong>{analysis.sourceFilename}</strong><p className="text-xs text-slate-500">Sample {dateLabel(analysis.reportDate)} · {analysis.laboratoryName||'Lab not identified'} · source file not retained</p></div><button onClick={()=>setItems(current=>current.map(item=>item.decision==='PENDING'&&item.bulkConfirmEligible?{...item,decision:'CONFIRMED'}:item))} className="min-h-11 rounded-xl bg-emerald-600 px-4 text-sm font-semibold text-white">Confirm all valid</button></div><div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-6">{[['Parameters',counts.total],['Mapped',counts.mapped],['Need review',counts.needs],['Abnormal',counts.abnormal],['Unmapped',counts.unmapped],['Rejected',counts.rejected]].map(([label,value])=><div key={label} className="rounded-xl bg-white p-3"><p className="text-xs text-slate-500">{label}</p><p className="text-lg font-semibold">{value}</p></div>)}</div></div><div className="mt-4 grid gap-3 sm:grid-cols-[1fr_auto_auto]"><input aria-label="Search biomarker" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search biomarker" className="min-h-11 rounded-xl border px-3"/><select aria-label="Filter biomarkers" value={filter} onChange={e=>setFilter(e.target.value)} className="min-h-11 rounded-xl border px-3">{FILTERS.map(x=><option key={x}>{x}</option>)}</select><select aria-label="Sort biomarkers" value={sort} onChange={e=>setSort(e.target.value)} className="min-h-11 rounded-xl border px-3">{['Report order','Name','Abnormal first'].map(x=><option key={x}>{x}</option>)}</select></div><div className="mt-5 space-y-6">{groups.map(([panel,rows])=><section key={panel}><div className="mb-2 flex justify-between"><h4 className="font-semibold">{panel}</h4><span className="text-xs text-slate-500">{rows.length} results</span></div><div className="space-y-3">{rows.map(item=><Row key={item.rowIdentity} item={item} onDecision={decide} onCorrection={correct}/>)}</div></section>)}</div><footer className="sticky bottom-0 mt-5 border-t bg-white py-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-semibold">{counts.ready} ready to save · {items.filter(x=>x.decision==='PENDING').length} need review · {counts.rejected} excluded</p><p className="text-xs text-slate-500">Only confirmed or corrected results are saved.</p></div><button disabled={busy||!counts.ready||correctionIncomplete} onClick={save} className="min-h-11 rounded-xl bg-blue-600 px-5 font-semibold text-white disabled:opacity-40">{busy?'Saving biomarkers…':'Save to Client Profile'}</button></div></footer></div>}</section></div>}</>;
}
